   var entireRoster=w.units;var previousPositions=w.units.ToDictionary(u=>u,u=>u.transform.position);engineer.transform.position=new Vector3(-44,-27);enemy.transform.position=new Vector3(44,-27);foreach(var ordinary in new[]{infantry,tank,mountain}){ordinary.transform.position=fort.transform.position+Vector3.left*.4f;ordinary.GetComponent<CampaignUnit>().fortTarget=null;ordinary.GetComponent<CampaignUnit>().AttackRemaining=0;w.units=new[]{ordinary};hp=fort.Health;CampaignCombatSolver.Resolve(w.campaign,.1f);Near(fort.Health,hp,"ordinary weapon cannot damage fort "+ordinary.combatDefinition.role);Check(!fort.Destroyed,"fort remains intact after ordinary fire");}enemy.transform.position=fort.transform.position;tank.transform.position=fort.transform.position+Vector3.left*.4f;tank.GetComponent<CampaignUnit>().AttackRemaining=0;w.units=new[]{tank,enemy};hp=fort.Health;float protectedHp=enemy.Personnel;CampaignCombatSolver.Resolve(w.campaign,.1f);Near(fort.Health,hp,"ordinary fire leaves fort intact with protected garrison");Near(enemy.Personnel,protectedHp,"existing fort cover is preserved");var campaign=w.campaign;w.campaign=null;Check(!w.GetComponent<CombinedArmsWorld>().PermitMovement(tank,fort.transform.position+Vector3.left,fort.transform.position+Vector3.right)&&!fort.Destroyed,"tank cannot crush fort through legacy movement");w.campaign=campaign;foreach(var role in new[]{UnitRole.Artillery,UnitRole.RocketArtillery}){var gun=entireRoster.First(u=>u.ownerId=="A"&&u.combatDefinition.role==role);gun.transform.position=fort.transform.position+Vector3.left*2;w.units=new[]{gun};hp=fort.Health;campaign.Shell(fort.transform.position,.65f,20,gun.unitId,"A");Check(fort.Health<hp,"artillery impact damages fort "+role);}w.units=entireRoster;foreach(var pair in previousPositions)pair.Key.transform.position=pair.Value;
   enemy.transform.position=new Vector3(44,-27);fort.ownerId="A";Check(targetOrders.QueueFortPursuit(engineer,fort),"engineer can still dismantle own fort by clicking");hp=fort.Health;engineer.GetComponent<CampaignUnit>().AttackRemaining=0;CampaignCombatSolver.Resolve(w.campaign,.1f);Check(fort.Health<hp,"explicit own-fort dismantle deals damage only to selected fort");targetOrders.CancelFor(engineer,true);var hud=UnityEngine.Object.FindObjectOfType<CampaignHUD>();hud.SelectUnit(engineer);var labels=hud.GetComponentsInChildren<Button>(true).Select(b=>b.GetComponentInChildren<Text>()).Where(t=>t!=null).Select(t=>t.text).ToArray();Check(!labels.Contains("拆除防线")&&!labels.Contains("拆除工事")&&!labels.Contains("攻击敌方工事"),"engineer panel has no demolition mode button");fort.Demolish();
  }
  static void Poll(){try{if(EditorApplication.timeSinceStartup-start>120)throw new Exception("timeout");if(!EditorApplication.isPlaying||Time.time<.7f)return;var w=UnityEngine.Object.FindObjectOfType<BattleWorld>();if(w==null||!w.Initialized)return;Test(w);Finish(null);}catch(Exception e){Finish(e);}}
  static void Finish(Exception e){if(e!=null){rows.Add("FAIL "+e);Debug.LogException(e);}File.WriteAllText(Path.Combine(Application.dataPath,"../verification-fire-sharing.txt"),string.Join("\n",rows));SessionState.SetBool(Key,false);EditorApplication.update-=Poll;EditorApplication.Exit(e==null?0:1);}
